#include "Bridge.h"
#include <stdio.h>
int main(int argc,char **argv){if(argc<4)return 2;if(!emu_start(argv[1],argv[2],argv[3])){fprintf(stderr,"FAIL %s\n",emu_error());return 1;}uint64_t imported=emu_sram_hash();for(int i=0;i<180;i++)emu_run();unsigned long frames=emu_frames(),audio=emu_audio_samples();uint64_t before=emu_sram_hash();int saved=emu_save();printf("frames=%lu audio_samples=%lu geometry=%dx%d save=%d imported=%llx\n",frames,audio,emu_width(),emu_height(),saved,(unsigned long long)imported);emu_stop();if(!emu_start(argv[1],argv[2],argv[3]))return 1;for(int i=0;i<180;i++)emu_run();uint64_t after=emu_sram_hash();printf("save_reopen_match=%d before=%llx after=%llx\n",before==after,(unsigned long long)before,(unsigned long long)after);emu_stop();return frames>100&&audio>0&&saved&&before==after?0:1;}
